1	use std::collections::HashSet;
2	
3	use callisto_model::{
4	    CommandRunner, CratePublish, DepKind, NpmMainPublish, PackageId, PublishPlan, PublishTarget, PypiPublish,
5	    RegistryKey, ReleaseEntry, SCHEMA_VERSION,
6	};
7	use callisto_vcs::GitDataSource;
8	
9	use crate::error::GraphError;
10	use crate::resolver::DependencyResolver;
11	use crate::toposort::toposort_impl;
12	use crate::Workspace;
13	
14	/// Edge kinds cascade/version-bump propagation cares about: a `Dev`-only
15	/// dependency change correctly never forces a consumer's version to bump.
16	const CASCADE_ORDERING_KINDS: &[DepKind] = &[DepKind::Runtime, DepKind::Build, DepKind::Optional];
17	
18	/// Edge kinds publish ordering cares about: cascade's kinds, plus `Dev`.
19	/// `cargo publish` (run without `--no-verify`, see `publish_client.rs`)
20	/// re-extracts the packaged tarball and does a real local build to verify
21	/// it, which needs *every* dependency in the crate's `Cargo.toml` —
22	/// `[dev-dependencies]` included — resolvable from the registry. A
23	/// dev-dependency on a workspace sibling published in the same batch
24	/// therefore still needs that sibling to publish first, even though the
25	/// two crates have no cascade-relevant ordering constraint between them.
26	const PUBLISH_ORDERING_KINDS: &[DepKind] = &[DepKind::Runtime, DepKind::Build, DepKind::Optional, DepKind::Dev];
27	
28	/// Computes the order packages must be published in.
29	///
30	/// This is a thin, purpose-named wrapper around [`toposort_impl`] (the
31	/// generic algorithm, reused as-is) rather than a generic
32	/// `DependencyResolverExt::toposort()` on a shared trait — it exists
33	/// specifically for `plan_publish` below, its only caller, and its
34	/// semantics are publish-specific, not "the one true topological sort."
35	///
36	/// Tries [`PUBLISH_ORDERING_KINDS`] first (including `Dev`, unlike cascade's
37	/// own [`CASCADE_ORDERING_KINDS`]) so a dev-dependency on a same-batch
38	/// sibling publishes in the right order. `Dev` edges are best-effort, not a
39	/// hard requirement, precisely because mutual dev-only dependencies between
40	/// two otherwise-unrelated packages are a legitimate pattern (e.g. two
41	/// crates each dev-depending on the other for cross-integration tests) —
42	/// unlike `Runtime`/`Build`/`Optional`, which must never cycle, a `Dev`
43	/// cycle must not hard-fail the whole publish plan. If including `Dev`
44	/// edges would produce a cycle, this falls back to
45	/// [`CASCADE_ORDERING_KINDS`] alone, which is guaranteed not to introduce a
46	/// *new* cycle here since it is a strict subset of the edges just proven
47	/// cyclic — accepting the original race this function exists to close for
48	/// that one pair, rather than failing the entire plan over it.
49	fn publish_order<D: DependencyResolver + ?Sized>(
50	    resolver: &D,
51	    subset: &HashSet<PackageId>,
52	) -> Result<Vec<PackageId>, GraphError> {
53	    let all_pkg_ids: Vec<PackageId> = resolver.packages().map(|p| p.id.clone()).collect();
54	    let edges_of = |id: &PackageId| -> Vec<(PackageId, DepKind)> {
55	        resolver.dependencies_of(id).map(|e| (e.to.clone(), e.kind)).collect()
56	    };
57	
58	    match toposort_impl(subset, &all_pkg_ids, PUBLISH_ORDERING_KINDS, edges_of) {
59	        Ok(order) => Ok(order),
60	        Err(GraphError::Cycle { .. }) => toposort_impl(subset, &all_pkg_ids, CASCADE_ORDERING_KINDS, edges_of),
61	        Err(e) => Err(e),
62	    }
63	}
