66	pub struct PublishOptions {
67	    /// When non-empty, only packages whose bare name (without ecosystem prefix)
68	    /// appears in this list are included in the plan. An empty `only` list
69	    /// means "include all packages" (the default).
70	    pub only: Vec<String>,
71	}
