73	/// Validates a `publishConfig.registry` URL from a package's own
74	/// `package.json` before it's used as an `npm publish --registry`/`npm
75	/// view --registry` target (both run with `NPM_TOKEN` live in CI).
76	///
77	/// `publishConfig.registry` is attacker-controllable (a PR author sets
78	/// their own `package.json`) and must never be trusted verbatim. Two
79	/// checks, mirroring the leading-`-` flag-injection guard on package names
80	/// (see `SubprocessRegistryClient::npm_publish`):
81	///
82	/// 1. Must use `https` -- a scheme downgrade is rejected even if the host
83	///    would otherwise be approved.
84	/// 2. Must exactly match a `url` on an `npm`-kind entry in
85	///    `callisto.toml`'s `[registries]` table.
86	///
87	/// No configured npm registries means no override is ever approved --
88	/// `callisto.toml`, not `package.json`, is the source of truth for where
89	/// credentialed publish requests can go.
90	fn validate_npm_registry_url(
91	    url: &str,
92	    package: &PackageId,
93	    registries: &std::collections::BTreeMap<RegistryKey, crate::config::RegistryConfig>,
94	) -> Result<(), GraphError> {
95	    let is_approved = url.starts_with("https://")
96	        && registries
97	            .values()
98	            .any(|cfg| cfg.kind == Ecosystem::Npm && cfg.url.as_deref() == Some(url));
99	
100	    if is_approved {
101	        Ok(())
102	    } else {
103	        Err(GraphError::UntrustedNpmRegistry {
104	            package: package.clone(),
105	            url: url.to_string(),
106	        })
107	    }
108	}
