110	/// Resolves a package's `changelog_section` for `plan_publish`: reads the file at
111	/// `ws_root.join(changelog_rel_path)` and extracts the `## {ver}` section via
112	/// `callisto_changelog::extract_section`. Every non-fatal outcome (file not found, no
113	/// matching heading, empty matched section, or an unreadable file) leaves the return value
114	/// `None` and pushes exactly one Warning diagnostic into `diagnostics` rather than aborting
115	/// the plan -- `ChangelogSectionNotFound` for the first three (AC-10b, AC-11, AC-12),
116	/// `ChangelogReadError` for a read failure that is not "file does not exist" (AC-12c).
117	fn resolve_changelog_section(
118	    ws_root: &std::path::Path,
119	    changelog_rel_path: &std::path::Path,
120	    pkg_id: &callisto_model::PackageId,
121	    ver: &callisto_model::Version,
122	    diagnostics: &mut Vec<callisto_model::Diagnostic>,
123	) -> Option<String> {
124	    let full_path = ws_root.join(changelog_rel_path);
125	    let content = match std::fs::read_to_string(&full_path) {
126	        Ok(c) => c,
127	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
128	            diagnostics.push(callisto_model::Diagnostic {
129	                code: callisto_model::DiagnosticCode::ChangelogSectionNotFound,
130	                severity: callisto_model::DiagnosticSeverity::Warning,
131	                message: format!(
132	                    "no changelog file found at `{}` for package `{}`",
133	                    changelog_rel_path.display(),
134	                    pkg_id.display_name()
135	                ),
136	                package: Some(pkg_id.clone()),
137	                path: Some(changelog_rel_path.to_path_buf()),
138	                escalated_by: None,
139	                governed_by: None,
140	            });
141	            return None;
142	        }
143	        Err(e) => {
144	            diagnostics.push(callisto_model::Diagnostic {
145	                code: callisto_model::DiagnosticCode::ChangelogReadError,
146	                severity: callisto_model::DiagnosticSeverity::Warning,
147	                message: format!(
148	                    "could not read changelog at `{}` for package `{}`: {e}",
149	                    changelog_rel_path.display(),
150	                    pkg_id.display_name()
151	                ),
152	                package: Some(pkg_id.clone()),
153	                path: Some(changelog_rel_path.to_path_buf()),
154	                escalated_by: None,
155	                governed_by: None,
156	            });
157	            return None;
158	        }
159	    };
160	
161	    match callisto_changelog::extract_section(&content, ver) {
162	        Some(section) => Some(section.to_string()),
163	        None => {
164	            diagnostics.push(callisto_model::Diagnostic {
165	                code: callisto_model::DiagnosticCode::ChangelogSectionNotFound,
166	                severity: callisto_model::DiagnosticSeverity::Warning,
167	                message: format!(
168	                    "no `## {}` section found in `{}` for package `{}`",
169	                    ver.render(),
170	                    changelog_rel_path.display(),
171	                    pkg_id.display_name()
172	                ),
173	                package: Some(pkg_id.clone()),
174	                path: Some(changelog_rel_path.to_path_buf()),
175	                escalated_by: None,
176	                governed_by: None,
177	            });
178	            None
179	        }
180	    }
181	}
