183	pub fn plan_publish<R: CommandRunner, D: DependencyResolver>(
184	    ws: &Workspace<'_, R, D>,
185	    opts: &PublishOptions,
186	) -> Result<PublishPlan, GraphError> {
187	    let mut rust_crates = Vec::new();
188	    let mut npm_main_packages = Vec::new();
189	    let mut npm_platform_packages = Vec::new();
190	    let mut pypi_packages = Vec::new();
191	    let mut releases = Vec::new();
192	
193	    let base_versions = ws.base_versions()?;
194	    let inference = crate::infer::NoInference;
195	    let mut diagnostics: Vec<callisto_model::Diagnostic> = Vec::new();
196	    let version_plan = match crate::commands::version::plan_version(
197	        ws,
198	        &inference,
199	        &crate::commands::version::VersionOptions::default(),
200	    ) {
201	        Ok(plan) => Some(plan),
202	        Err(e) => {
203	            diagnostics.push(callisto_model::Diagnostic {
204	                code: callisto_model::DiagnosticCode::ChangesetReadError,
205	                severity: callisto_model::DiagnosticSeverity::Warning,
206	                message: format!("Could not read changesets: {e}"),
207	                package: None,
208	                path: None,
209	                escalated_by: None,
210	                governed_by: None,
211	            });
212	            None
213	        }
214	    };
215	
216	    // Build a single lookup map once — eliminates O(N) scans inside the topo loop
217	    // (PERF-003/004/005). Keys and values are borrowed from the graph for the
218	    // lifetime of this function, so no extra clones are needed for the lookups.
219	    let pkg_map: std::collections::HashMap<&callisto_model::PackageId, &callisto_model::Package> =
220	        ws.graph.packages().map(|p| (&p.id, p)).collect();
221	    let all_ids: std::collections::HashSet<_> = pkg_map.keys().map(|&id| id.clone()).collect();
222	    let topo_ids = publish_order(&ws.graph, &all_ids)?;
223	
224	    // `Workspace::git_access` (native gix, falling back to the
225	    // `CommandRunner` shell path when unavailable -- always true on
226	    // wasm32) rather than a fresh `GitAccess::discover`, which has no
227	    // such fallback: on wasm32, native discovery unconditionally fails
228	    // (gix is excluded from that target's dependency set), so `head_sha`
229	    // was always `None` there, silently omitting every release entry
230	    // from the plan. Sharing the workspace-scoped instance also means
231	    // this command's tag-index lookup below (via `ws.tags()`) reuses the
232	    // same discovery instead of paying for a second one.
233	    let head_sha = match ws.git_access().head_sha() {
234	        Ok(sha) => Some(sha),
235	        Err(e) => {
236	            diagnostics.push(callisto_model::Diagnostic {
237	                code: callisto_model::DiagnosticCode::GitDiscoveryFailed,
238	                severity: callisto_model::DiagnosticSeverity::Warning,
239	                message: format!("Could not resolve HEAD SHA: {e}; release entries will be omitted from the plan"),
240	                package: None,
241	                path: None,
242	                escalated_by: None,
243	                governed_by: None,
244	            });
245	            None
246	        }
247	    };
248	
249	    // Build the tag index once before the loop. If git is unavailable (no
250	    // .git directory, no git binary, or any other VCS error), emit a soft
251	    // diagnostic and treat every package as a release candidate for this
252	    // plan (tag_match = false). Hard-propagating the error here would
253	    // contradict the soft GitDiscoveryFailed diagnostic already emitted by
254	    // the head_sha block above.
255	    let tag_index = match ws.tags() {
256	        Ok(idx) => Some(idx),
257	        Err(e) => {
258	            diagnostics.push(callisto_model::Diagnostic {
259	                code: callisto_model::DiagnosticCode::GitDiscoveryFailed,
260	                severity: callisto_model::DiagnosticSeverity::Warning,
261	                message: format!("Could not read git tags: {e}; all packages treated as release candidates"),
262	                package: None,
263	                path: None,
264	                escalated_by: None,
265	                governed_by: None,
266	            });
267	            None
268	        }
269	    };
270	
271	    for id in &topo_ids {
272	        let pkg = match pkg_map.get(id) {
273	            Some(&p) => p,
274	            None => continue,
275	        };
276	
277	        let bump_info = version_plan
278	            .as_ref()
279	            .and_then(|plan| plan.bumps.iter().find(|b| b.package == pkg.id));
280	
281	        let (is_release, ver) = if let Some(bump) = bump_info {
282	            (true, bump.to.clone())
283	        } else {
284	            let cur_ver = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
285	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
286	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
287	                    field: "version",
288	                })
289	            })?;
290	            let tag_match = tag_index
291	                .and_then(|idx| idx.last_tag(&pkg.id))
292	                .map(|t| t.version == cur_ver)
293	                .unwrap_or(false);
294	            (!tag_match, cur_ver)
295	        };
296	
297	        if is_release {
298	            // Single exhaustive dispatch match over every configured target —
299	            // replaces the old ad-hoc `.any(matches!(...))` membership checks,
300	            // which silently dropped `PublishTarget::NuGet`/`GitHubRelease` on
301	            // the floor with no diagnostic. `PublishTarget` is `#[non_exhaustive]`
302	            // (defined in callisto-model), so a wildcard arm is still required
303	            // by the compiler even though every current variant is named
304	            // explicitly below; the wildcard exists only to catch a future
305	            // variant added without a corresponding arm here, not to silently
306	            // swallow one of today's variants.
307	            let mut publishes_cargo = false;
308	            let mut publishes_npm = false;
309	            let mut publishes_pypi = false;
310	            let mut npm_registry_url: Option<String> = None;
311	            let mut npm_access: Option<callisto_model::NpmAccess> = None;
312	            // True once at least one configured target has a real dispatch
313	            // implementation. Drives the release-tag/ReleaseEntry gate below —
314	            // a package configured only with not-yet-implemented targets
315	            // (NuGet, GitHubRelease) must not get a ReleaseEntry claiming a
316	            // release happened when nothing was actually publishable.
317	            let mut has_dispatchable_target = false;
318	
319	            for target in &pkg.publish_to {
320	                match target {
321	                    callisto_model::PublishTarget::CratesIo => {
322	                        publishes_cargo = true;
323	                        has_dispatchable_target = true;
324	                    }
325	                    callisto_model::PublishTarget::Npm { registry, access } => {
326	                        publishes_npm = true;
327	                        has_dispatchable_target = true;
328	                        // Extract the private registry URL and access
329	                        // setting from the first Npm target, both read
330	                        // from `publishConfig` in package.json.
331	                        if npm_registry_url.is_none() {
332	                            if let Some(url) = registry {
333	                                validate_npm_registry_url(url, &pkg.id, &ws.config.registries)?;
334	                            }
335	                            npm_registry_url = registry.clone();
336	                            npm_access = *access;
337	                        }
338	                    }
339	                    callisto_model::PublishTarget::Pypi { .. } => {
340	                        publishes_pypi = true;
341	                        has_dispatchable_target = true;
342	                    }
343	                    callisto_model::PublishTarget::NuGet { .. } => {
344	                        diagnostics.push(callisto_model::Diagnostic {
345	                            code: callisto_model::DiagnosticCode::PublishTargetNotImplemented,
346	                            severity: callisto_model::DiagnosticSeverity::Warning,
347	                            message: format!(
348	                                "package `{}` configures publish-to = [\"nuget\"], but NuGet \
349	                                 publishing is not yet implemented; this target will not be \
350	                                 published",
351	                                pkg.id.display_name()
352	                            ),
353	                            package: Some(pkg.id.clone()),
354	                            path: None,
355	                            escalated_by: None,
356	                            governed_by: None,
357	                        });
358	                    }
359	                    callisto_model::PublishTarget::GitHubRelease => {
360	                        diagnostics.push(callisto_model::Diagnostic {
361	                            code: callisto_model::DiagnosticCode::PublishTargetNotImplemented,
362	                            severity: callisto_model::DiagnosticSeverity::Warning,
363	                            message: format!(
364	                                "package `{}` configures publish-to = [\"github-release\"], but \
365	                                 GitHub Release publishing is not yet implemented; this target \
366	                                 will not be published",
367	                                pkg.id.display_name()
368	                            ),
369	                            package: Some(pkg.id.clone()),
370	                            path: None,
371	                            escalated_by: None,
372	                            governed_by: None,
373	                        });
374	                    }
375	                    callisto_model::PublishTarget::None => {}
376	                    #[allow(unreachable_patterns)]
377	                    _ => {
378	                        diagnostics.push(callisto_model::Diagnostic {
379	                            code: callisto_model::DiagnosticCode::PublishTargetNotImplemented,
380	                            severity: callisto_model::DiagnosticSeverity::Warning,
381	                            message: format!(
382	                                "package `{}` configures a publish-to target with no \
383	                                 implemented dispatch; this target will not be published",
384	                                pkg.id.display_name()
385	                            ),
386	                            package: Some(pkg.id.clone()),
387	                            path: None,
388	                            escalated_by: None,
389	                            governed_by: None,
390	                        });
391	                    }
392	                }
393	            }
394	
395	            let is_platform_pkg = pkg
396	                .manifests
397	                .iter()
398	                .any(|m| matches!(m.role, callisto_model::ManifestRole::Platform { .. }));
399	
400	            // Resolve the package directory (relative to workspace root) from
401	            // the first manifest path. All manifests for a package share the
402	            // same parent directory, so any first manifest is correct.
403	            let pkg_dir = pkg
404	                .manifests
405	                .first()
406	                .and_then(|m| m.path.parent())
407	                .map(|p| p.to_path_buf())
408	                // SAFETY: unwrap_or_default produces an empty PathBuf only when
409	                // no manifests exist; in that case package_dir being empty just
410	                // disables the pre-publish version check, which is acceptable.
411	                .unwrap_or_default();
412	
413	            if publishes_cargo {
414	                rust_crates.push(CratePublish {
415	                    name: pkg.id.name().to_string(),
416	                    version: ver.clone(),
417	                    publish_to: callisto_model::RegistryKey(callisto_model::RegistryKey::CRATES_IO.to_string()),
418	                    registry: None,
419	                    package_dir: if pkg_dir.as_os_str().is_empty() {
420	                        None
421	                    } else {
422	                        Some(pkg_dir.clone())
423	                    },
424	                });
425	            }
426	
427	            if publishes_npm {
428	                let tag = if ver.is_prerelease() {
429	                    Some("next".to_string())
430	                } else {
431	                    None
432	                };
433	
434	                // Determine npm access level. Honour the operator's explicit
435	                // `publishConfig.access` from package.json first, whatever it
436	                // is -- "restricted", or "public" (which a bare bool used to
437	                // silently drop for unscoped packages, since it collapsed
438	                // "absent" and "explicit public" to the same value). Only
439	                // fall back to the `@scope/name`-implies-public heuristic
440	                // when nothing was explicitly set. npm's `--access` CLI flag
441	                // takes full precedence over publishConfig.access, so
442	                // callisto must read and propagate the intent explicitly
443	                // here.
444	                let access = npm_access.or_else(|| {
445	                    if pkg.id.name().starts_with('@') {
446	                        Some(callisto_model::NpmAccess::Public)
447	                    } else {
448	                        None
449	                    }
450	                });
451	
452	                if is_platform_pkg {
453	                    npm_platform_packages.push(callisto_model::NpmPublish {
454	                        name: pkg.id.name().to_string(),
455	                        version: ver.clone(),
456	                        publish_to: callisto_model::RegistryKey(callisto_model::RegistryKey::NPM.to_string()),
457	                        package_dir: pkg_dir.clone(),
458	                        registry: npm_registry_url.clone(),
459	                        tag: tag.clone(),
460	                        access,
461	                    });
462	                } else {
463	                    let platform_deps: Vec<String> = ws
464	                        .graph
465	                        .dependencies_of(&pkg.id)
466	                        .filter(|edge| {
467	                            pkg_map
468	                                .get(&edge.to)
469	                                .map(|p| {
470	                                    p.manifests
471	                                        .iter()
472	                                        .any(|m| matches!(m.role, callisto_model::ManifestRole::Platform { .. }))
473	                                })
474	                                .unwrap_or(false)
475	                        })
476	                        .map(|edge| edge.to.name().to_string())
477	                        .collect();
478	
479	                    npm_main_packages.push(NpmMainPublish {
480	                        name: pkg.id.name().to_string(),
481	                        version: ver.clone(),
482	                        publish_to: callisto_model::RegistryKey(callisto_model::RegistryKey::NPM.to_string()),
483	                        package_dir: pkg_dir.clone(),
484	                        registry: npm_registry_url,
485	                        tag,
486	                        access,
487	                        depends_on_platforms: platform_deps,
488	                    });
489	                }
490	            }
491	
492	            if publishes_pypi {
493	                // Extract the optional custom index URL from the first Pypi
494	                // target. Multiple Pypi entries on the same package are not
495	                // expected, so only the first is consulted.
496	                let index = pkg
497	                    .publish_to
498	                    .iter()
499	                    .find_map(|t| {
500	                        if let callisto_model::PublishTarget::Pypi { index } = t {
501	                            Some(index.clone())
502	                        } else {
503	                            None
504	                        }
505	                    })
506	                    .flatten();
507	
508	                pypi_packages.push(PypiPublish {
509	                    name: pkg.id.name().to_string(),
510	                    version: ver.clone(),
511	                    publish_to: RegistryKey(RegistryKey::PYPI.to_string()),
512	                    package_dir: pkg_dir,
513	                    index,
514	                });
515	            }
516	
517	            if !pkg.publish_to.is_empty()
518	                && !pkg.publish_to.iter().all(|t| *t == PublishTarget::None)
519	                && has_dispatchable_target
520	            {
521	                // Both head_sha and tag_index must be available: head_sha supplies
522	                // the commit to tag and tag_index supplies the template to render
523	                // the tag name. When tag_index is None (ws.tags() failed and was
524	                // soft-handled above), release entries are omitted — consistent
525	                // with the GitDiscoveryFailed diagnostic already pushed.
526	                if let (Some(ref sha), Some(idx)) = (&head_sha, tag_index) {
527	                    let changelog_section = pkg.changelog.as_ref().and_then(|ch_path| {
528	                        resolve_changelog_section(&ws.root, ch_path, &pkg.id, &ver, &mut diagnostics)
529	                    });
530	                    releases.push(ReleaseEntry {
531	                        package: pkg.id.clone(),
532	                        tag_name: idx.template(&pkg.id).render(&ver),
533	                        sha: sha.clone(),
534	                        changelog_section,
535	                        is_prerelease: ver.is_prerelease(),
536	                    });
537	                }
538	            }
539	        }
540	    }
541	
542	    // Apply the `only` filter: when the caller specifies a set of package names,
543	    // drop everything not in that set from every ecosystem list. An empty `only`
544	    // means "all packages".
545	    if !opts.only.is_empty() {
546	        let keep = |name: &str| opts.only.iter().any(|n| n == name);
547	        rust_crates.retain(|c| keep(&c.name));
548	        npm_main_packages.retain(|c| keep(&c.name));
549	        npm_platform_packages.retain(|c| keep(&c.name));
550	        pypi_packages.retain(|c| keep(&c.name));
551	        releases.retain(|r| keep(r.package.name()));
552	
553	        // Validate: every requested name must match at least one retained entry.
554	        // A typo in --package silently produces an empty plan and exits 0 without
555	        // this check, making CI report "nothing to publish" instead of an error.
556	        let retained: std::collections::HashSet<&str> = rust_crates
557	            .iter()
558	            .map(|c| c.name.as_str())
559	            .chain(npm_main_packages.iter().map(|c| c.name.as_str()))
560	            .chain(npm_platform_packages.iter().map(|c| c.name.as_str()))
561	            .chain(pypi_packages.iter().map(|c| c.name.as_str()))
562	            .collect();
563	        for requested in &opts.only {
564	            if !retained.contains(requested.as_str()) {
565	                return Err(crate::error::GraphError::UnknownPackage {
566	                    id: callisto_model::PackageId::Bare(requested.clone()),
567	                });
568	            }
569	        }
570	    }
571	
572	    Ok(PublishPlan {
573	        schema_version: SCHEMA_VERSION,
574	        rust_crates,
575	        npm_main_packages,
576	        npm_platform_packages,
577	        pypi_packages,
578	        releases,
579	        diagnostics,
580	    })
581	}
