589	/// Maximum number of rate-limit retries per package before the orchestrator
590	/// gives up and records a failure. Prevents an infinite retry loop when a
591	/// registry consistently returns 429 responses with a short `retry_after`.
592	pub(crate) const MAX_RATE_LIMIT_RETRIES: usize = 10;
593	
594	/// Maximum `retry_after` duration (seconds) the orchestrator will honor
595	/// before treating the rate-limit as a hard failure.
596	const MAX_RETRY_AFTER_SECS: u64 = 600;
597	
598	/// Default fallback wait (seconds) when the registry does not supply a
599	/// `retry_after` value and the client cannot parse one from output.
600	pub(crate) const DEFAULT_RATE_LIMIT_WAIT_SECS: u64 = 60;
601	
602	/// Parses a numeric retry-after value (seconds) as reported by a registry
603	/// tool's output. Shared by [`PublishOrchestrator::parse_http_429_ttl`] and
604	/// by ecosystem [`RegistryClient`] implementations that need to extract a
605	/// retry duration from free-form subprocess output.
606	pub fn parse_retry_after(raw: &str) -> Option<Duration> {
607	    raw.trim().parse::<u64>().ok().map(Duration::from_secs)
608	}
