641	impl<R, P, T> PublishOrchestrator<R, P, T>
642	where
643	    R: RegistryClient,
644	    P: RateLimitPolicy,
645	    T: TimeProvider,
646	{
647	    pub fn new(client: R, policy: P, time: T) -> Self {
648	        Self {
649	            client,
650	            policy,
651	            time,
652	            progress: None,
653	        }
654	    }
