656	    /// Attach a progress callback that is invoked before each package publish
657	    /// attempt. The message includes the package name and version.
658	    pub fn with_progress<F: Fn(String) + Send + Sync + 'static>(mut self, f: F) -> Self {
659	        self.progress = Some(Box::new(f));
660	        self
661	    }
