673	    /// Attempts to publish every package in `plan` to its ecosystem
674	    /// registry, recording a per-package outcome (or failure) for each one
675	    /// rather than aborting the whole batch on the first error — one
676	    /// package's registry rejection or auth failure must not silently erase
677	    /// the fact that earlier packages in the same run genuinely published or
678	    /// were already present.
679	    pub fn execute(&self, plan: &PublishPlan, permit: &ApplyPermit) -> PublishReport {
680	        let mut attempts = Vec::new();
681	
682	        for rust_crate in &plan.rust_crates {
683	            let pkg_id = PackageId::Prefixed {
684	                ecosystem: Ecosystem::Cargo,
685	                name: rust_crate.name.clone(),
686	            };
687	            self.emit_progress(&rust_crate.name, &rust_crate.version);
688	            attempts.push(self.attempt_publish(pkg_id, rust_crate.version.clone(), permit));
689	        }
690	
691	        for npm_pkg in &plan.npm_platform_packages {
692	            let pkg_id = PackageId::Prefixed {
693	                ecosystem: Ecosystem::Npm,
694	                name: npm_pkg.name.clone(),
695	            };
696	            self.emit_progress(&npm_pkg.name, &npm_pkg.version);
697	            attempts.push(self.attempt_publish(pkg_id, npm_pkg.version.clone(), permit));
698	        }
699	
700	        for npm_pkg in &plan.npm_main_packages {
701	            let pkg_id = PackageId::Prefixed {
702	                ecosystem: Ecosystem::Npm,
703	                name: npm_pkg.name.clone(),
704	            };
705	            self.emit_progress(&npm_pkg.name, &npm_pkg.version);
706	            attempts.push(self.attempt_publish(pkg_id, npm_pkg.version.clone(), permit));
707	        }
708	
709	        for pypi_pkg in &plan.pypi_packages {
710	            let pkg_id = PackageId::Prefixed {
711	                ecosystem: Ecosystem::Pypi,
712	                name: pypi_pkg.name.clone(),
713	            };
714	            self.emit_progress(&pypi_pkg.name, &pypi_pkg.version);
715	            attempts.push(self.attempt_publish(pkg_id, pypi_pkg.version.clone(), permit));
716	        }
717	
718	        PublishReport {
719	            schema_version: callisto_model::SCHEMA_VERSION,
720	            attempts,
721	            diagnostics: Vec::new(),
722	        }
723	    }
724	
725	    fn attempt_publish(&self, package: PackageId, version: Version, permit: &ApplyPermit) -> PublishAttempt {
726	        let result = match self.publish_with_retry(&package, &version, permit) {
727	            Ok(PublishOutcome::Published) => PublishAttemptResult::Published,
728	            Ok(PublishOutcome::AlreadyPublished) => PublishAttemptResult::AlreadyPublished,
729	            Err(err) => PublishAttemptResult::Failed {
730	                kind: err.kind_str().to_string(),
731	                error: err.to_string(),
732	            },
733	        };
734	
735	        PublishAttempt {
736	            package,
737	            version,
738	            result,
739	        }
740	    }
741	
742	    fn publish_with_retry(
743	        &self,
744	        pkg_id: &PackageId,
745	        version: &Version,
746	        permit: &ApplyPermit,
747	    ) -> Result<PublishOutcome, RegistryError> {
748	        // Treat any is_published error as "unknown — proceed to publish". The
749	        // pre-check is an optional optimization, not a required gate. Propagating
750	        // errors here aborts the publish without ever calling publish(), which
751	        // records a misleading failure (e.g. "rateLimited") that never reached
752	        // the actual publish step.
753	        if self.client.is_published(pkg_id, version).unwrap_or(false) {
754	            return Ok(PublishOutcome::AlreadyPublished);
755	        }
756	
757	        let mut retries = 0usize;
758	        loop {
759	            match self.client.publish(pkg_id, version, permit) {
760	                // Both a fresh publish and a publish-time "already there"
761	                // classification are done-and-not-an-error: neither should
762	                // retry, and AlreadyPublished is treated identically to the
763	                // is_published short-circuit above.
764	                Ok(outcome @ (PublishOutcome::Published | PublishOutcome::AlreadyPublished)) => return Ok(outcome),
765	                Err(RegistryError::RateLimited(retry_after)) => {
766	                    if retry_after > Duration::from_secs(MAX_RETRY_AFTER_SECS) {
767	                        return Err(RegistryError::RateLimited(retry_after));
768	                    }
769	                    retries += 1;
770	                    if retries >= MAX_RATE_LIMIT_RETRIES {
771	                        return Err(RegistryError::Other(format!(
772	                            "rate-limited {MAX_RATE_LIMIT_RETRIES} consecutive times; giving up"
773	                        )));
774	                    }
775	                    self.policy.check_rate_limit(retry_after)?;
776	                    self.time.sleep(retry_after);
777	                }
778	                Err(RegistryError::AuthFailed(err)) => {
779	                    return Err(RegistryError::AuthFailed(err));
780	                }
781	                Err(err) => {
782	                    return Err(err);
783	                }
784	            }
785	        }
786	    }
787	}
