1	//! [`RegistryClient`] implementation that shells out to each ecosystem's own
2	//! publisher CLI (`cargo publish`, `npm publish`, `twine upload`) via
3	//! [`CommandRunner`], instead of talking to any registry's HTTP API
4	//! directly. This is a deliberate design constraint: registry HTTP protocols
5	//! are a moving target that the native tools already track for us, so we
6	//! never reimplement them here.
7	//!
8	//! [`PublishOrchestrator`](super::publish::PublishOrchestrator) is generic
9	//! over a single [`RegistryClient`] type, so this module exposes one
10	//! dispatching client ([`SubprocessRegistryClient`]) rather than three
11	//! separate types — it routes each call to the right ecosystem's command
12	//! construction/classification based on the [`PackageId`]'s ecosystem tag.
13	//!
14	//! ## Per-package publish metadata
15	//!
16	//! [`RegistryClient::publish`] only receives a [`PackageId`] and [`Version`].
17	//! To thread per-package metadata recorded in a
18	//! [`PublishPlan`](callisto_model::PublishPlan) entry — e.g.
19	//! `CratePublish::registry`, `NpmPublish::tag`/`access`, `PypiPublish::index`
20	//! — through this call boundary, callers **must** invoke
21	//! [`SubprocessRegistryClient::load_plan`] with the full plan before passing
22	//! the client to the orchestrator. The client stores the metadata in
23	//! per-ecosystem lookup maps keyed by package name and consults them at
24	//! dispatch time inside `RegistryClient::publish`.
25	
26	use std::collections::HashMap;
27	use std::path::PathBuf;
28	use std::time::Duration;
29	
30	use callisto_manifests::WorkspaceCargoResolver;
31	use callisto_model::{
32	    known_credential_env_values, normalize_pypi_package_name, redact_known_secrets, ApplyPermit, CommandOutput,
33	    CommandRunner, Ecosystem, NpmAccess, PackageId, PublishOutcome, RegistryClient, RegistryError, Version,
34	};
35	use toml;
36	
37	use super::publish::parse_retry_after;
38	
39	/// Maximum wall-clock time (in seconds) allowed for a single publish command
40	/// (`cargo publish`, `npm publish`, `twine upload`). If the process does not
41	/// exit within this window it is killed and the attempt is recorded as a
42	/// timeout failure.
43	const PUBLISH_TIMEOUT_SECS: u64 = 300;
44	
45	/// Per-package npm publish metadata stored in the metadata map.
46	struct NpmMeta {
47	    tag: Option<String>,
48	    access: Option<NpmAccess>,
49	    /// Private npm registry URL from `publishConfig.registry` in `package.json`.
50	    /// When `Some`, `--registry <url>` is appended to `npm publish` and
51	    /// `npm view`. When `None`, the public npm registry is used.
52	    registry: Option<String>,
53	}
54	
55	/// Dispatches [`RegistryClient`] calls to the right ecosystem CLI based on
56	/// each [`PackageId`]'s ecosystem tag.
57	///
58	/// Before calling through the [`RegistryClient`] trait, invoke
59	/// [`Self::load_plan`] so that per-package metadata (dist-tag, access level,
60	/// registry URL, private index URL, package directory) is threaded through to
61	/// the CLI args and working directory.
62	pub struct SubprocessRegistryClient<R: CommandRunner> {
63	    runner: R,
64	    /// Workspace root. Used as the base for resolving per-package directories
65	    /// and as the working directory for package managers that resolve packages
66	    /// by name from the workspace root (`cargo`, `pnpm`, `yarn`, `npm`).
67	    cwd: PathBuf,
68	    /// npm publish metadata keyed by package name.
69	    npm_meta: HashMap<String, NpmMeta>,
70	    /// Cargo registry name (e.g. `"my-private-registry"`) keyed by crate name.
71	    cargo_registry: HashMap<String, Option<String>>,
72	    /// Per-package directory (relative to workspace root) for Cargo crates.
73	    /// Used to read the on-disk `Cargo.toml` for a pre-publish version check.
74	    cargo_pkg_dir: HashMap<String, std::path::PathBuf>,
75	    /// Planned publish version per crate name, populated from the plan.
76	    cargo_planned_version: HashMap<String, Version>,
77	    /// PyPI index URL keyed by distribution name.
78	    pypi_index: HashMap<String, Option<String>>,
79	    /// Per-package directory (relative to workspace root) for npm packages,
80	    /// keyed by package name. Used for package managers that must be invoked
81	    /// from the package directory (bun).
82	    npm_pkg_dir: HashMap<String, PathBuf>,
83	    /// Per-package directory (relative to workspace root) for PyPI packages,
84	    /// keyed by distribution name. `twine upload` runs from this directory so
85	    /// that `dist/` resolves to the package's own dist directory in a monorepo.
