89	impl<R: CommandRunner> SubprocessRegistryClient<R> {
90	    pub fn new(runner: R, cwd: PathBuf) -> Self {
91	        Self {
92	            runner,
93	            cwd,
94	            npm_meta: HashMap::new(),
95	            cargo_registry: HashMap::new(),
96	            cargo_pkg_dir: HashMap::new(),
97	            cargo_planned_version: HashMap::new(),
98	            pypi_index: HashMap::new(),
99	            npm_pkg_dir: HashMap::new(),
100	            pypi_pkg_dir: HashMap::new(),
101	        }
102	    }
