104	    /// Pre-loads per-package publish metadata from a [`callisto_model::PublishPlan`]
105	    /// so that `RegistryClient::publish` can thread the correct dist-tag,
106	    /// access level, registry, and private index URL through to each
107	    /// ecosystem CLI invocation. Must be called before any publish attempt
108	    /// that should respect plan-level overrides.
109	    pub fn load_plan(&mut self, plan: &callisto_model::PublishPlan) {
110	        for pkg in &plan.npm_platform_packages {
111	            self.npm_meta.insert(
112	                pkg.name.clone(),
113	                NpmMeta {
114	                    tag: pkg.tag.clone(),
115	                    access: pkg.access,
116	                    registry: pkg.registry.clone(),
117	                },
118	            );
119	            self.npm_pkg_dir.insert(pkg.name.clone(), pkg.package_dir.clone());
120	        }
121	        for pkg in &plan.npm_main_packages {
122	            self.npm_meta.insert(
123	                pkg.name.clone(),
124	                NpmMeta {
125	                    tag: pkg.tag.clone(),
126	                    access: pkg.access,
127	                    registry: pkg.registry.clone(),
128	                },
129	            );
130	            self.npm_pkg_dir.insert(pkg.name.clone(), pkg.package_dir.clone());
131	        }
132	        for pkg in &plan.rust_crates {
133	            self.cargo_registry.insert(pkg.name.clone(), pkg.registry.clone());
134	            self.cargo_planned_version.insert(pkg.name.clone(), pkg.version.clone());
135	            if let Some(dir) = &pkg.package_dir {
136	                self.cargo_pkg_dir.insert(pkg.name.clone(), dir.clone());
137	            }
138	        }
139	        for pkg in &plan.pypi_packages {
140	            self.pypi_index.insert(pkg.name.clone(), pkg.index.clone());
141	            self.pypi_pkg_dir.insert(pkg.name.clone(), pkg.package_dir.clone());
142	        }
143	    }
