155	    /// For an internal existence/probe check, not a real publish action --
156	    /// see [`callisto_model::CommandRunner::run_quiet`]. Its stderr is
157	    /// expected to look like a failure on the common case (e.g. `npm view`
158	    /// against an unpublished package), so it must not stream live.
159	    fn run_quiet(&self, program: &str, args: &[&str]) -> Result<CommandOutput, RegistryError> {
160	        self.runner
161	            .run_quiet(program, args, &self.cwd, Duration::from_secs(PUBLISH_TIMEOUT_SECS))
162	            .map_err(|e| RegistryError::Other(e.to_string()))
163	    }
