531	impl<R: CommandRunner> RegistryClient for SubprocessRegistryClient<R> {
532	    fn is_published(&self, package: &PackageId, version: &Version) -> Result<bool, RegistryError> {
533	        match package {
534	            PackageId::Prefixed {
535	                ecosystem: Ecosystem::Npm,
536	                name,
537	                ..
538	            } => {
539	                let registry = self.npm_meta.get(name.as_str()).and_then(|m| m.registry.as_deref());
540	                self.npm_is_published(package, version, registry)
541	            }
542	
543	            // Cargo: no reliable cargo-CLI-only existence check exists
544	            // (crates.io has no local "is this on the index" subcommand
545	            // short of hitting its HTTP API, which this design deliberately
546	            // avoids). `publish()`'s own AlreadyPublished classification is
547	            // the real source of truth for Cargo.
548	            //
549	            // PyPI: twine's own --skip-existing flag absorbs idempotency at
550	            // upload time, so a pre-check buys nothing extra here either.
551	            PackageId::Prefixed {
552	                ecosystem: Ecosystem::Cargo | Ecosystem::Pypi,
553	                ..
554	            } => Ok(false),
555	
556	            other => Err(RegistryError::Other(format!(
557	                "no subprocess is_published check configured for package identity `{}`",
558	                other.display_name()
559	            ))),
560	        }
561	    }
562	
563	    fn publish(
564	        &self,
565	        package: &PackageId,
566	        version: &Version,
567	        _permit: &ApplyPermit,
568	    ) -> Result<PublishOutcome, RegistryError> {
569	        match package {
570	            PackageId::Prefixed {
571	                ecosystem: Ecosystem::Cargo,
572	                name,
573	                ..
574	            } => {
575	                let registry = self.cargo_registry.get(name.as_str()).and_then(|r| r.as_deref());
576	                self.cargo_publish(package, registry)
577	            }
578	            PackageId::Prefixed {
579	                ecosystem: Ecosystem::Npm,
580	                name,
581	                ..
582	            } => {
583	                let meta = self.npm_meta.get(name.as_str());
584	                let tag = meta.and_then(|m| m.tag.as_deref());
585	                let access = meta.and_then(|m| m.access.as_ref());
586	                let registry = meta.and_then(|m| m.registry.as_deref());
587	                self.npm_publish(package, tag, access, registry)
588	            }
589	            PackageId::Prefixed {
590	                ecosystem: Ecosystem::Pypi,
591	                name,
592	                ..
593	            } => {
594	                let index = self.pypi_index.get(name.as_str()).and_then(|i| i.as_deref());
595	                self.pypi_publish(package, version, index)
596	            }
597	            other => Err(RegistryError::Other(format!(
598	                "no subprocess publisher configured for package identity `{}`",
599	                other.display_name()
600	            ))),
601	        }
602	    }
603	}
