1060	        fn run(&self, _program: &str, _args: &[&str], _cwd: &std::path::Path) -> Result<CommandOutput, CommandError> {
1061	            self.live_called.store(true, std::sync::atomic::Ordering::SeqCst);
1062	            Ok(self.response.clone())
1063	        }
1064	
1065	        fn run_with_timeout(
1066	            &self,
1067	            _program: &str,
1068	            _args: &[&str],
1069	            _cwd: &std::path::Path,
1070	            _timeout: Duration,
1071	        ) -> Result<CommandOutput, CommandError> {
1072	            self.live_called.store(true, std::sync::atomic::Ordering::SeqCst);
1073	            Ok(self.response.clone())
1074	        }
1075	
1076	        fn run_quiet(
1077	            &self,
1078	            _program: &str,
1079	            _args: &[&str],
1080	            _cwd: &std::path::Path,
1081	            _timeout: Duration,
1082	        ) -> Result<CommandOutput, CommandError> {
1083	            self.quiet_called.store(true, std::sync::atomic::Ordering::SeqCst);
1084	            Ok(self.response.clone())
1085	        }
1086	    }
